import { JxInput, JxButton, JxToast, JxField } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [showToast, setShowToast] = useState(false);

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!email) return;

    setEmail('');
    setShowToast(true);
  };

  return (
    <div className="jx-stack" style={{ position: 'relative' }}>
      <form onSubmit={handleSubmit} className="jx-stack jx-gap-md">
        <JxField label="Email">
          <JxInput
            type="email"
            name="email"
            placeholder="you@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
        </JxField>
        <JxButton type="submit" variant="primary">
          Подписаться
        </JxButton>
      </form>

      {showToast && (
        <JxToast
          variant="success"
          title="Готово"
          description="Письмо с подтверждением подписки отправлено на вашу почту."
          onClose={() => setShowToast(false)}
          className="jx-toast-corner"
        />
      )}
    </div>
  );
}

